let params=new URLSearchParams(location.search),lang=['es','en','pt'].includes(params.get('lang'))?params.get('lang'):'es',cycle=params.get('cycle')==='annual'?'annual':'monthly',plan=['free','pro','team'].includes(params.get('plan'))?params.get('plan'):'pro';
let path=location.pathname.replace(/\/$/,'')||'/';const routes=['/','/checkout','/upgrade','/confirmation','/terms','/privacy','/refunds','/contact'];if(!routes.includes(path))path='/';const ids=['free','pro','team'];let c=copy[lang];
localPricing.legal(copy);
function url(route='/',p=plan){return `${route}?lang=${lang}&cycle=${cycle}&plan=${p}&currency=${localPricing.preference}`;}function money(n){return localPricing.format(n,lang)}function amount(p=plan){return p==='free'?0:(p==='team'?79:29)*(cycle==='annual'?10:1)}function price(p=plan){return `${money(amount(p))}<small>${cycle==='annual'?c.year:c.month}</small>`}function go(route,p=plan){location.href=url(route,p)}
function header(){return `<div class="notice">${c.demo}</div><div class="wrap"><header class="nav"><a class="brand" href="${url('/')}"><span class="mark">e</span>entrega<span style="color:#86a26c">.</span></a><nav class="links">${c.nav.map((v,i)=>`<a href="${url('/')}#${['product','how','pricing','faq'][i]}">${v}</a>`).join('')}</nav><div class="actions"><a class="btn small ghost" href="/app?lang=${lang}">${({es:"Abrir aplicación",en:"Open app",pt:"Abrir aplicativo"})[lang]}</a><select id="language" aria-label="Language / Idioma"><option value="es" ${lang==='es'?'selected':''}>ES · Español</option><option value="en" ${lang==='en'?'selected':''}>EN · English</option><option value="pt" ${lang==='pt'?'selected':''}>PT · Português</option></select><a class="btn small" href="${url('/')}#pricing">${c.start} <span>↗</span></a></div></header></div>${localPricing.selector(lang)}`}
function footer(){return `<div class="wrap"><footer><div class="footer-top"><div><a class="brand" href="${url('/')}">entrega.</a><p class="micro">${c.footer}</p></div><div class="footer-links">${c.legal.map((v,i)=>`<a href="${url(['/terms','/privacy','/refunds','/contact'][i])}">${v}</a>`).join('')}</div></div><div class="footnote">© ${new Date().getFullYear()} Entrega. ${c.footnote}<br>CNPJ: 67.842.341/0001-85<br><a href="https://www.exchangerate-api.com" target="_blank" rel="noopener noreferrer">Rates By Exchange Rate API</a></div></footer></div>`}
function mockup(){return `<div class="stage"><div class="app-window"><div class="window-top"><b>entrega.</b><span>${c.workspace}</span><div class="dots"><i></i><i></i><i></i></div></div><div class="workspace"><div class="side"><div class="active">▦ ${c.projects}</div><div>◷ ${c.deliveries}</div><div>◎ ${c.clients}</div></div><div class="work-main"><div class="work-heading"><div><span class="micro">${c.workspace}</span><h3>${c.board}</h3></div><span class="avatar">AB</span></div><div class="board">${c.columns.map((v,i)=>`<div class="col">${v} <span style="float:right">1</span><div class="card-mini"><div class="thumb ${['','pink','blue'][i]}">${['STUDIO / 01','SOCIAL / 02','FILM / 03'][i]}</div><b>${c.cards[i]}</b><div class="tiny-tag">${['01','02','03'][i]} / ${c.columns[i]}</div><div style="border-top:1px solid #eee;margin-top:5px;padding-top:7px">↗ ${c.review}</div></div></div>`).join('')}</div></div></div></div><div class="floating"><span class="check">✓</span><div><b>${c.approval}</b><br><span class="micro">${c.approved}</span></div></div><div class="caption">${c.preview}</div></div>`}
function landing(){return `<main class="wrap"><section class="hero"><div><div class="eyebrow">${c.eyebrow}</div><h1>${c.hero}</h1><p>${c.desc}</p><div class="hero-ctas"><a class="btn" href="#pricing">${c.start} ↗</a><a class="btn ghost" href="#how">${c.see}</a></div><div class="micro">${c.micro}</div></div>${mockup()}</section><div class="strip"><span class="eyebrow">${c.for}</span>${c.audience.map(v=>`<strong>${v}</strong>`).join('')}</div><section class="section" id="product"><div class="intro"><div class="eyebrow">${c.featEye}</div><h2>${c.featTitle}</h2><p>${c.featDesc}</p></div><div class="features">${c.features.map((v,i)=>`<article class="feature"><span class="num">${['▦','↗','✓'][i]}</span><h3>${v[0]}</h3><p>${v[1]}</p></article>`).join('')}</div></section><section id="how" class="workflow"><div><div class="eyebrow">${c.howEye}</div><h2>${c.howTitle}</h2><p>${c.howDesc}</p><a class="btn lime" href="#pricing">${c.start} ↗</a></div><div>${c.steps.map((v,i)=>`<div class="step"><span>0${i+1}</span><div><h3>${v[0]}</h3><p>${v[1]}</p></div></div>`).join('')}</div></section><section class="section" id="pricing"><div class="intro center"><div class="eyebrow">${c.priceEye}</div><h2>${c.priceTitle}</h2><p>${c.priceDesc}</p></div><div class="billing" role="group" aria-label="${c.period}"><button data-cycle="monthly" class="${cycle==='monthly'?'on':''}" aria-pressed="${cycle==='monthly'}">${c.monthly}</button><button data-cycle="annual" class="${cycle==='annual'?'on':''}" aria-pressed="${cycle==='annual'}">${c.yearly} <span class="save">${c.saving}</span></button></div><div class="pricing">${ids.map((p,i)=>`<article class="plan ${i===1?'featured':''}">${i===1?`<span class="badge">${c.popular}</span>`:''}<h3>${c.names[i]}</h3><p>${c.planDesc[i]}</p><div class="price">${p==='free'?money(0):price(p)}</div><div class="charge">${p==='free'?c.free:cycle==='annual'?`${c.billed} ${money(amount(p))}`:c.monthlyCharge}</div><ul>${c.planFeatures[i].map(f=>`<li>${f}</li>`).join('')}</ul><a class="btn ${i===1?'':'ghost'}" href="${url('/checkout',p)}">${i===0?c.freeCta:c.choose+' '+c.names[i]} ↗</a></article>`).join('')}</div><p class="micro" style="text-align:center;margin-top:25px">${c.currency}</p></section><section id="faq" class="faq section" style="padding-top:10px"><h2>${c.faqTitle}</h2>${c.faqs.map(v=>`<details><summary>${v[0]}</summary><p>${v[1]}</p></details>`).join('')}</section><section class="closing"><div><h2>${c.closeTitle}</h2><p>${c.closeDesc}</p></div><a class="btn" href="#pricing">${c.start} ↗</a></section></main>`}
function crumbs(n){return `<div class="breadcrumbs">${c.crumbs.map((s,i)=>`<span class="${i===n?'current':''}">${i+1}. ${s}</span>`).join('<span>—</span>')}</div>`}
function checkout(){return `<main class="wrap"><div class="flow">${crumbs(0)}<a class="micro" href="${url('/')}#pricing">← ${c.back}</a><h1>${c.checkoutTitle}</h1><p>${c.checkoutDesc}</p><div class="flow-grid"><form id="checkout-form" class="panel"><h3>${c.details}</h3><label class="field">${c.name}<input name="name" autocomplete="name" required maxlength="100"></label><label class="field">${c.email}<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label class="field">${c.business}<input name="business" autocomplete="organization" maxlength="100"></label><label class="consent"><input type="checkbox" required><span>${c.consent} <a href="${url('/terms')}" target="_blank">${c.legal[0]}</a> · <a href="${url('/refunds')}" target="_blank">${c.legal[2]}</a></span></label><button class="btn full" type="submit">${c.continue} →</button><div class="note">${c.checkoutNote}</div></form><aside class="panel"><h3>${c.summary}</h3><div class="summary-row"><strong>${c.names[ids.indexOf(plan)]}</strong><a href="${url('/')}#pricing">${c.nav[2]} ↗</a></div><ul style="padding-left:20px;font-size:14px;color:var(--muted)">${c.planFeatures[ids.indexOf(plan)].map(v=>`<li>${v}</li>`).join('')}</ul><div class="summary-row"><span>${c.period}</span><span>${plan==='free'?c.free:cycle==='annual'?c.yearly:c.monthly}</span></div><div class="summary-row total"><span>${c.total}</span><span>${money(amount())}</span></div><div class="summary-row"><span>${c.today}</span><strong>${c.zero}</strong></div><p class="micro">${plan==='free'?c.free:c.renew}</p><p class="micro">${c.currency}</p></aside></div></div></main>`}
function upgrade(){return `<main class="wrap"><div class="flow">${crumbs(1)}<div class="up"><div class="eyebrow" style="justify-content:center">${c.upgradeEye}</div><h1>${c.upgradeTitle}</h1><p>${c.upgradeDesc}</p><div class="panel"><h3>${c.upgradeLabel}</h3><p>${c.upgradeText}</p><ul>${c.planFeatures[2].map(v=>`<li>${v}</li>`).join('')}</ul><div class="summary-row"><span>${c.difference}</span><strong>+ ${money(amount('team')-amount('pro'))}${cycle==='annual'?c.year:c.month}</strong></div><div class="summary-row total"><span>${c.total}</span><span>${money(amount('team'))}${cycle==='annual'?c.year:c.month}</span></div><p class="micro">${c.replacement}</p><p class="micro">${c.renew}</p><a class="btn full" href="${url('/confirmation','team')}">${c.upgradeAccept} →</a></div><a class="text-btn" href="${url('/confirmation','pro')}">${c.skip}</a></div></div></main>`}
function confirmation(){return `<main class="wrap"><div class="flow">${crumbs(2)}<div class="up"><div class="success-icon">✓</div><h1>${c.successTitle}</h1><p>${c.successDesc}</p><div class="panel"><div class="summary-row"><span>${c.selected}</span><strong>${c.names[ids.indexOf(plan)]}</strong></div><div class="summary-row"><span>${c.total}</span><strong>${money(amount())}${plan==='free'?'':cycle==='annual'?c.year:c.month}</strong></div><div class="summary-row total"><span>${c.today}</span><span>${money(0)}</span></div><p class="micro">${c.successNote}</p></div><a class="btn" href="${url('/')}">${c.again} ↗</a></div></div></main>`}
function legal(){const i=['/terms','/privacy','/refunds','/contact'].indexOf(path);return `<main class="wrap"><article class="legal"><a class="micro" href="${url('/')}">← ${c.again}</a><h1>${i===3?c.contactTitle:c.legal[i]}</h1><div class="note">${c.legalDraft}</div>${i===3?`<p>${c.contactText}</p><p>${c.contactMore}</p>`:c[['termsSections','privacySections','refundSections'][i]].map(v=>`<h2>${v[0]}</h2><p>${v[1]}</p>`).join('')}</article></main>`}
function render(){const draft=[...document.querySelectorAll('#checkout-form input')].map(el=>({name:el.name,type:el.type,value:el.value,checked:el.checked}));c=localPricing.decorate(copy[lang],lang);document.documentElement.lang=lang==='pt'?'pt-BR':lang;document.title=c.title;document.querySelector('meta[name="description"]').content=c.desc;document.getElementById('app').innerHTML=header()+({'/':landing,'/checkout':checkout,'/upgrade':upgrade,'/confirmation':confirmation}[path]||legal)()+footer();document.getElementById('currency')?.addEventListener('change',e=>localPricing.select(e.target.value));document.querySelectorAll('#checkout-form input').forEach((el,i)=>{const d=draft[i];if(d&&d.name===el.name&&d.type===el.type){el.value=d.value;el.checked=d.checked}});document.getElementById('language').addEventListener('change',e=>{lang=e.target.value;history.replaceState(null,'',url(path)+location.hash);render()});document.querySelectorAll('[data-cycle]').forEach(b=>b.addEventListener('click',()=>{cycle=b.dataset.cycle;history.replaceState(null,'',url(path)+location.hash);const y=window.scrollY;render();window.scrollTo(0,y)}));document.getElementById('checkout-form')?.addEventListener('submit',e=>{e.preventDefault();if(localPricing.ready)go(plan==='pro'?'/upgrade':'/confirmation')});const submit=document.querySelector('#checkout-form button[type=submit]');if(submit)submit.disabled=!localPricing.ready}document.addEventListener('pricing-change',render);render();localPricing.refresh();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'configure_demo_plan',description:'Select the language, plan and billing period and open the demo checkout. Does not purchase anything or create an account.',inputSchema:{type:'object',properties:{language:{type:'string',enum:['es','en','pt']},plan:{type:'string',enum:ids},billing:{type:'string',enum:['monthly','annual']}},required:['language','plan','billing'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!['es','en','pt'].includes(input.language)||!ids.includes(input.plan)||!['monthly','annual'].includes(input.billing))throw new Error('Invalid selection');lang=input.language;plan=input.plan;cycle=input.billing;path='/checkout';history.pushState(null,'',url(path));render();window.scrollTo(0,0);return {language:lang,plan,billing:cycle,demo:true,charge:0}}})).catch(()=>{});}catch{}}
